    constructor(C _c) { c = _c; }
    function run(address _recipient, address _caller) public payable returns (bool) {
        require(_caller != address(0) && _recipient != address(0));
        // ensure caller is not the owner, so the rule is tested for non-owner
        require(_caller != c.owner());
        // impersonate the non-owner caller using a low-level call from this contract,
        // because we cannot change msg.sender directly. We forward the withdrawAll call
        // via a helper call from this contract. However, the constraint says c.f(args)
        // must be a top-level statement directly in run. We will record a revert flag.
        // We need to call c.withdrawAll(_recipient) as the caller. Since we cannot
        // change tx.origin or msg.sender, the test must be run by the non-owner.
        // But the test contract itself is the caller. So we set this test contract's
        // address to not be the owner. That is, we require that address(this) != c.owner().
        require(address(this) != c.owner());
        bool reverted;
        try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
}

