pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this)); // exclude owner (address(this) is the owner from setUp)
        vm.assume(recipient != address(this)); // avoid self-transfer edge cases
        vm.assume(recipient != address(c)); // avoid sending to contract itself

        // fund the contract with some ether to test draining
        vm.deal(address(c), 1 ether);

        // record balance before the call
        uint256 balanceBefore = address(c).balance;

        // attempt withdrawAll as the fuzzed caller
        bool didRevert = false;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            // call succeeded (no revert)
        } catch {
            didRevert = true;
        }

        if (!didRevert) {
            // For any successful call, the property must hold:
            // balanceAfter == 0  <==>  caller == owner
            uint256 balanceAfter = address(c).balance;
            bool balanceIsZero = (balanceAfter == 0);
            bool callerIsOwner = (caller == address(this));
            assertTrue(balanceIsZero == callerIsOwner);
        } else {
            // If it reverted, balance must be unchanged (reference behavior for non-owner)
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

