pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.deal(address(c), amount);
        c.withdrawAll(recipient);
        // After owner (address(this)) calls withdrawAll, the contract's balance should still be accessible.
        // In the correct version, balance is transferred to recipient, so contract balance becomes 0.
        // In the buggy version, selfdestruct destroys the contract, so reading balance returns 0 as well.
        // The difference is that in the buggy version, the contract is destroyed and its code is gone.
        // Therefore, the contract's balance is not a reliable differentiator after the call.
        // Instead, we check whether the contract still exists by measuring its codesize.
        uint256 size;
        assembly { size := extcodesize(c) }
        // Reference: contract still exists after transfer, codesize > 0.
        // Bug: contract selfdestructed, codesize == 0.
        assertTrue(size > 0);
    }
}

