pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // Restrict to admissible domain: recipient != address(c) and amount > 0
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);
